'use strict';

/**
* LAPACK routine to equilibrate a real symmetric matrix using the scaling factors in a vector `S`.
*
* @module @stdlib/lapack/base/dlaqsy
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlaqsy = require( '@stdlib/lapack/base/dlaqsy' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
*
* dlaqsy( 'row-major', 'upper', 3, A, 3, S, 0.0625, 9.0 );
* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dlaqsy = require( '@stdlib/lapack/base/dlaqsy' );
*
* var A = new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 5.0, 6.0, 3.0, 6.0, 9.0 ] );
* var S = new Float64Array( [ 0.25, 2.0, 4.0 ] );
*
* dlaqsy.ndarray( 'upper', 3, A, 3, 1, 0, S, 1, 0, 0.0625, 9.0 );
* // A => <Float64Array>[ 0.0625, 1.0, 3.0, 2.0, 20.0, 48.0, 3.0, 6.0, 144.0 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlaqsy;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlaqsy = main;
} else {
	dlaqsy = tmp;
}


// EXPORTS //

module.exports = dlaqsy;

// exports: { "ndarray": "dlaqsy.ndarray" }
